package com.tiny.snake; import android.app.Activity; import android.content.Context; import android.graphics.*; import android.os.*; import android.view.*; import java.util.Random; public class MainActivity extends Activity { @Override protected void onCreate(Bundle b) { super.onCreate(b); requestWindowFeature(Window.FEATURE_NO_TITLE); getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN, WindowManager.LayoutParams.FLAG_FULLSCREEN); setContentView(new SnakeView(this)); } private class SnakeView extends View { int[] x = new int[400], y = new int[400]; int len = 3, dx = 1, dy = 0, fx, fy, cols = 15, rows = 15; Paint p = new Paint(); Handler h = new Handler(); Random r = new Random(); float sx, sy; public SnakeView(Context c) { super(c); reset(); h.postDelayed(new Runnable() { public void run() { update(); invalidate(); h.postDelayed(this, 150); } }, 150); } void reset() { len = 3; dx = 1; dy = 0; for (int i = 0; i < len; i++) { x[i] = 5 - i; y[i] = 5; } spawn(); } void spawn() { if (cols > 0 && rows > 0) { fx = r.nextInt(cols); fy = r.nextInt(rows); } } void update() { if (cols <= 0 || rows <= 0) return; for (int i = len - 1; i > 0; i--) { x[i] = x[i - 1]; y[i] = y[i - 1]; } x[0] += dx; y[0] += dy; if (x[0] < 0 || x[0] >= cols || y[0] < 0 || y[0] >= rows) { reset(); return; } for (int i = 1; i < len; i++) if (x[0] == x[i] && y[0] == y[i]) { reset(); return; } if (x[0] == fx && y[0] == fy) { if (len < 400) len++; spawn(); } } @Override protected void onDraw(Canvas c) { c.drawColor(Color.BLACK); int w = getWidth(), h = getHeight(); if (w == 0 || h == 0) return; int ts = w / cols, nr = h / ts; if (nr != rows) { rows = nr; spawn(); } p.setColor(Color.RED); c.drawRect(fx * ts, fy * ts, (fx + 1) * ts, (fy + 1) * ts, p); p.setColor(Color.GREEN); for (int i = 0; i < len; i++) c.drawRect(x[i] * ts, y[i] * ts, (x[i] + 1) * ts, (y[i] + 1) * ts, p); p.setColor(Color.WHITE); p.setTextSize(40); c.drawText("Score: " + (len - 3), 30, 60, p); } @Override public boolean onTouchEvent(MotionEvent e) { if (e.getAction() == MotionEvent.ACTION_DOWN) { sx = e.getX(); sy = e.getY(); } else if (e.getAction() == MotionEvent.ACTION_UP) { float ex = e.getX() - sx, ey = e.getY() - sy; if (Math.abs(ex) > Math.abs(ey)) { if (ex > 30 && dx == 0) { dx = 1; dy = 0; } else if (ex < -30 && dx == 0) { dx = -1; dy = 0; } } else { if (ey > 30 && dy == 0) { dx = 0; dy = 1; } else if (ey < -30 && dy == 0) { dx = 0; dy = -1; } } } return true; } } }
